routes.script:
EXEC INSERT INTO {{t:proc}} (quote_id, name, fee) VALUES ({{id}}, {{body.name}}, {{body.fee}});
EXEC UPDATE {{t:main}} SET process_fee = process_fee + {{body.fee}}, total = total + {{body.fee}} WHERE id = {{id}};
RETURN 201 { "ok": true };

LET $q = QUERY SELECT * FROM {{t:main}} WHERE id = {{id}} LIMIT 1;
LET $p = QUERY SELECT * FROM {{t:proc}} WHERE quote_id = {{id}};
RETURN 200 { "quote": $q.rows, "processes": $p.rows };
